/**
 * Shared academic catalogue (Domain → Field → Specialty → Program).
 * Semesters / UE / Subjects are generated by the Student-Records mock (see mocks/handlers/records.ts).
 * All data is synthetic.
 */
import type { AcademicLevel, Cycle } from '@/types/common';

export interface CatalogDomain {
  id: string;
  code: string;
  name: string;
  nameAr: string;
  description: string;
}
export interface CatalogField {
  id: string;
  code: string;
  domainId: string;
  name: string;
  nameAr: string;
  description: string;
}
export interface CatalogSpecialty {
  id: string;
  code: string;
  fieldId: string;
  name: string;
  nameAr: string;
  description: string;
}
export interface CatalogProgramVersion {
  id: string;
  label: string;
  startYear: number;
  endYear: number | null;
  isCurrent: boolean;
}
export interface CatalogProgram {
  id: string;
  code: string;
  level: AcademicLevel;
  cycle: Cycle;
  specialtyId: string;
  name: string;
  nameAr: string;
  totalCredits: number;
  versions: CatalogProgramVersion[];
  currentVersionId: string;
}

