const LEVELS: { level: AcademicLevel; cycle: Cycle }[] = [
  { level: 'L1', cycle: 'licence' },
  { level: 'L2', cycle: 'licence' },
  { level: 'L3', cycle: 'licence' },
  { level: 'M1', cycle: 'master' },
  { level: 'M2', cycle: 'master' },
];

export const programs: CatalogProgram[] = specialties.flatMap((s) =>
  LEVELS.map(({ level, cycle }) => {
    const id = `prg-${s.code.toLowerCase()}-${level.toLowerCase()}`;
    return {
      id,
      code: `${s.code}-${level}`,
      level,
      cycle,
      specialtyId: s.id,
      name: `${cycle === 'licence' ? 'Licence' : 'Master'} ${s.name}`,
      nameAr: `${cycle === 'licence' ? 'ليسانس' : 'ماستر'} ${s.nameAr}`,
      totalCredits: 60,
      currentVersionId: `${id}-v2`,
      versions: [
        { id: `${id}-v1`, label: 'Maquette 2020', startYear: 2020, endYear: 2023, isCurrent: false },
        { id: `${id}-v2`, label: 'Maquette 2024', startYear: 2024, endYear: null, isCurrent: true },
      ],
    };
  }),
);

export const programById = (id: string) => programs.find((p) => p.id === id);
export const specialtyById = (id: string) => specialties.find((s) => s.id === id);
export const fieldById = (id: string) => fields.find((f) => f.id === id);
export const domainById = (id: string) => domains.find((d) => d.id === id);
export const specialtyOfProgram = (p: CatalogProgram) => specialtyById(p.specialtyId)!;
